  async function worker() {
    while (true) {
      const page = next++;
      if (page > pages) return;
      const body = await cachedPage(page);
      documents.push(...body.data);
      await sleep(100);
    }
  }
  await Promise.all(Array.from({ length: CONCURRENCY }, worker));

