cd /tmp/shurik-workspace-Yuk6Of && python3 - <<'EOF'
import urllib.request,urllib.parse,json,os,time,threading,collections,sys
UA={'User-Agent':'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map catalogue)'}
d=json.load(open('.cache/slub/kf/es.json'))
ids=[h['_source']['map_id'] for h in d['hits']['hits']]
outdir='.cache/slub/kf/meta'; os.makedirs(outdir,exist_ok=True)
lock=threading.Lock(); work=iter(ids); counts=collections.Counter(); errors=[]; done=[0]
def worker():
    while True:
        with lock:
            try: mid=next(work)
            except StopIteration: return
        fn=os.path.join(outdir, mid.split(':id-')[-1]+'.json')
        if os.path.exists(fn):
            try:
                counts[json.load(open(fn)).get('license')]+=1
            except: pass
            done[0]+=1
            continue
        url='https://api.kartenforum.slub-dresden.de/maps/'+urllib.parse.quote(mid,safe=':')
        ok=False
        for attempt in range(3):
            try:
                req=urllib.request.Request(url,headers=UA)
                body=urllib.request.urlopen(req,timeout=30).read()
                j=json.loads(body)
                open(fn,'wb').write(body)
                with lock:
                    counts[j.get('license')]+=1; done[0]+=1
                    if done[0]%500==0: print('done',done[0],dict(counts),flush=True)
                ok=True; break
            except Exception as e:
                if attempt==2:
                    with lock: errors.append((mid,str(e)))
                time.sleep(1+attempt)
        if not ok:
            with lock: done[0]+=1
        time.sleep(0.08)
ts=[threading.Thread(target=worker) for _ in range(5)]
[t.start() for t in ts]; [t.join() for t in ts]
print('FINAL done',done[0],'errors',len(errors),'counts',counts)
json.dump(dict(counts),open('.cache/slub/kf/license-counts.json','w'),indent=1)
EOF

