#!/usr/bin/env node
/**
 * SLUB Dresden "Virtuelles Kartenforum" georeferenced-map harvest (member 0,
 * sourcing swarm 2026-10-20).
 *
 * Discovery uses the public Kartenforum search index at
 *   https://search.kartenforum.slub-dresden.de/vk20/_search
 * and the item metadata service at
 *   https://api.kartenforum.slub-dresden.de/maps/<map_id>
 *
 * Rights are read per item from the `license` field of that official metadata
 * response. This lane admits only the affirmative Creative Commons
 * Attribution-ShareAlike values `CC-BY-SA` and `CC-BY-SA 4.0`. `CC-BY-SA & PuD`
 * is deliberately withheld until the second term is documented; it is not
 * guessed to mean public domain. Rights-reserved (`RV-FZ-*`), blank,
 * third-party attribution strings and non-commercial values stay out.
 *
 * The Kartenforum publishes a georeferenced footprint polygon and TMS tile
 * pyramids for most records. Those are recorded as the documented extent and a
 * real XYZ/TMS overlay; no alignment is invented for records that lack them.
 * The physical `measures` string is kept separately from the geographic extent.
 *
 * Usage:
 *   node scripts/harvest-slub-kartenforum.mjs
 *   node scripts/harvest-slub-kartenforum.mjs --no-write
 *   node scripts/harvest-slub-kartenforum.mjs --refresh   # re-fetch everything
 *
 * The index and per-item metadata are cached under .cache/slub/kf/ (git-ignored)
 * and the run resumes from that cache. `--refresh` is deliberately not needed
 * for a normal rebuild.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const value = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/slub/kf');
const REFRESH = has('refresh');
const WRITE = !has('no-write');
const RETRIEVED = '2026-10-20';
const UA = 'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map catalogue)';
const SEARCH = 'https://search.kartenforum.slub-dresden.de/vk20/_search';
const METADATA = 'https://api.kartenforum.slub-dresden.de/maps';
const PROVIDER = 'slub-kartenforum';
const SHARD = '/data/records/kartenforum.json';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Upstream licence strings admitted by this lane, verbatim. */
export const ADMITTED_LICENSES = new Set(['CC-BY-SA', 'CC-BY-SA 4.0']);

/**
 * Rights gate. Returns the catalogue rights fields for an admitted upstream
 * licence string, or null. `CC-BY-SA & PuD` is intentionally not admitted: the
 * `PuD` term is not defined in the public API and must not be guessed.
 */
export function licenceFields(license) {
  const raw = String(license ?? '').trim();
  if (!ADMITTED_LICENSES.has(raw)) return null;
  const version = raw === 'CC-BY-SA 4.0' ? '4.0' : null;
  return {
    rights: raw,
    rightsBasis: 'cc-by-sa',
    license: raw,
    licenseVersion: version,
    licenseUrl: version ? 'https://creativecommons.org/licenses/by-sa/4.0/' : 'https://creativecommons.org/licenses/by-sa/',
    rightsStatement: version
      ? 'CC BY-SA 4.0, as stated in the item metadata service of the SLUB Virtuelles Kartenforum.'
      : 'CC BY-SA, as stated in the item metadata service of the SLUB Virtuelles Kartenforum; the service does not state a version for this item.',
  };
}

/** GeoJSON Polygon/MultiPolygon → WGS84 bounding box, or null. */
export function bboxOfGeometry(geometry) {
  const type = geometry?.type;
  if (type !== 'Polygon' && type !== 'MultiPolygon') return null;
  const polygons = type === 'Polygon' ? [geometry.coordinates] : geometry.coordinates;
  const points = [];
  for (const polygon of Array.isArray(polygons) ? polygons : []) {
    for (const ring of Array.isArray(polygon) ? polygon : []) {
      for (const point of Array.isArray(ring) ? ring : []) points.push(point);
    }
  }
  const lons = points.map((p) => Number(p?.[0])).filter(Number.isFinite);
  const lats = points.map((p) => Number(p?.[1])).filter(Number.isFinite);
  if (lons.length < 3 || lats.length < 3) return null;
  const box = { west: Math.min(...lons), east: Math.max(...lons), south: Math.min(...lats), north: Math.max(...lats) };
  if (!(box.west < box.east && box.south < box.north)) return null;
  if (box.west < -180 || box.east > 180 || box.south < -90 || box.north > 90) return null;
  return box;
}

/** First TMS base URL → a tile template the client can render. */
export function tmsTemplate(tmsUrls) {
  const base = Array.isArray(tmsUrls) ? String(tmsUrls[0] ?? '').replace(/\/+$/, '') : '';
  if (!/^https:\/\/tms-[12]\.kartenforum\.slub-dresden\.de\/[a-z]+\/[A-Za-z0-9_.-]+$/.test(base)) return null;
  // The server is a standard OSGeo TMS pyramid: its y counts from the south.
  return `${base}/{z}/{x}/{-y}.png`;
}

const YEAR = (value) => {
  const match = String(value ?? '').match(/(\d{4})/);
  return match ? Number(match[1]) : null;
};

/**
 * Build one catalogue record from the official metadata response and the search
 * hit. Returns `{ record }` or `{ reason }` so withholding stays countable.
 */
export function kartenforumRecord(meta, source) {
  if (!meta || typeof meta !== 'object') return { reason: 'missing metadata' };
  const mapId = String(meta.map_id ?? '');
  if (!mapId.startsWith('oai:de:slub-dresden:vk:id-')) return { reason: 'unexpected map id' };
  const license = licenceFields(meta.license);
  if (!license) return { reason: `rights withheld: ${String(meta.license ?? '').trim() || 'no licence field'}` };
  const title = String(meta.title ?? '').trim();
  if (!title) return { reason: 'missing title' };
  if (/\btest\b/i.test(title)) return { reason: 'upstream test record' };
  const thumbnail = String(meta.link_thumb_mid ?? meta.link_thumb_small ?? '').trim();
  if (!/^https:\/\/(fotothek|thumbnail\.kartenforum)\.slub-dresden\.de\//.test(thumbnail)) {
    return { reason: 'missing or unexpected thumbnail' };
  }
  const id = mapId.split(':id-').pop();
  const year = YEAR(source?.time_published ?? meta.time_of_publication);
  const bbox = bboxOfGeometry(source?.geometry);
  const owner = String(meta.owner ?? '').trim() || 'SLUB / Deutsche Fotothek';
  const viewerUrl = `https://kartenforum.slub-dresden.de/?map_id=${encodeURIComponent(mapId)}`;
  const record = {
    id: `${PROVIDER}:${id}`,
    title,
    creators: [],
    providerId: PROVIDER,
    institution: owner === 'Deutsche Fotothek' ? 'Deutsche Fotothek (SLUB Dresden)' : 'Sächsische Landesbibliothek – Staats- und Universitätsbibliothek Dresden (SLUB)',
    ...license,
    rightsUrl: meta.permalink ? String(meta.permalink) : viewerUrl,
    attribution: `${owner}; ${title}; ${viewerUrl}`,
    creditLine: `${owner}, Virtuelles Kartenforum der SLUB Dresden`,
    recordUrl: viewerUrl,
    viewerUrl,
    thumbnail,
    imageUrl: thumbnail,
    type: 'map',
    collection: 'Virtuelles Kartenforum',
    originalCollection: 'Karten und Ansichten',
    originalRecordId: mapId,
    fileName: meta.file_name ?? null,
    permalink: meta.permalink ?? null,
    ppn: meta.ppn ?? null,
    metadataSource: `${METADATA}/${mapId}`,
    languages: [],
    geoNote: bbox
      ? 'Extent is the bounding box of the georeferenced footprint polygon published by the SLUB Virtuelles Kartenforum. Provider-supplied alignment; not independently re-verified.'
      : 'The SLUB Virtuelles Kartenforum metadata does not state a footprint for this scan; no place anchor or boundary is inferred.',
  };
  if (meta.description) record.description = String(meta.description);
  if (meta.title_serie) record.series = String(meta.title_serie);
  if (meta.measures) record.physicalSize = String(meta.measures);
  if (year !== null) {
    record.dateDisplay = String(year);
    record.yearStart = year;
    record.yearEnd = year;
  }
  if (meta.time_of_publication) record.publicationDate = String(meta.time_of_publication).slice(0, 10);
  if (bbox) record.extent = bbox;
  const keywords = String(source?.keywords ?? '')
    .split(/\n+/)
    .map((s) => s.trim())
    .filter(Boolean);
  if (keywords.length) record.subjects = [...new Set(keywords)];
  return { record };
}

/** A real TMS overlay for a record with both a template and a documented extent. */
export function overlayOf(record, source) {
  const template = tmsTemplate(source?.tms_urls);
  if (!template || !record.extent) return null;
  return {
    id: `kf-${record.id.split(':').pop()}`,
    kind: 'xyz',
    providerId: PROVIDER,
    title: record.title,
    recordId: record.id,
    urlTemplate: template,
    extent: record.extent,
    attribution: record.creditLine,
    license: record.rights,
    historical: true,
    timeValues: [],
    mapYear: record.yearStart ?? null,
  };
}

async function fetchJson(url, { attempts = 4, timeout = 45000 } = {}) {
  let last;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const res = await fetch(url, {
        headers: { accept: 'application/json', 'user-agent': UA },
        signal: AbortSignal.timeout(timeout),
      });
      if (res.ok) return await res.json();
      last = new Error(`${res.status} ${url}`);
      if (res.status !== 429 && res.status < 500) break;
    } catch (error) {
      last = error;
    }
    await sleep(500 * attempt);
  }
  throw last;
}

async function cachedSearch() {
  const file = resolve(CACHE, 'es.json');
  if (!REFRESH) {
    try {
      return JSON.parse(await readFile(file, 'utf8'));
    } catch {
      // fetch below
    }
  }
  const body = await fetchJson(SEARCH, { attempts: 2, timeout: 60000 }).catch(() => null);
  const document =
    body ??
    (await (async () => {
      const res = await fetch(SEARCH, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'user-agent': UA },
        body: JSON.stringify({ size: 10000, query: { exists: { field: 'map_id' } } }),
        signal: AbortSignal.timeout(120000),
      });
      if (!res.ok) throw new Error(`${res.status} ${SEARCH}`);
      return res.json();
    })());
  await mkdir(CACHE, { recursive: true });
  await writeFile(file, JSON.stringify(document));
  return document;
}

async function metadataFor(mapId) {
  const id = mapId.split(':id-').pop();
  const file = resolve(CACHE, 'meta', `${id}.json`);
  if (!REFRESH) {
    try {
      return JSON.parse(await readFile(file, 'utf8'));
    } catch {
      // fetch below
    }
  }
  const body = await fetchJson(`${METADATA}/${mapId}`);
  await mkdir(dirname(file), { recursive: true });
  await writeFile(file, JSON.stringify(body));
  return body;
}

async function pool(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  async function worker() {
    while (true) {
      const i = next++;
      if (i >= items.length) return;
      out[i] = await fn(items[i], i);
      await sleep(70);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

/** Head a URL with a small range so a tile/image is not downloaded whole. */
async function probe(url, accept) {
  try {
    const res = await fetch(url, {
      headers: { accept, 'user-agent': UA, range: 'bytes=0-2047' },
      signal: AbortSignal.timeout(30000),
    });
    return { status: res.status, type: res.headers.get('content-type') };
  } catch (error) {
    return { status: 0, type: String(error.message) };
  }
}

function tileAt(box, z) {
  const lon = (box.west + box.east) / 2;
  const lat = (box.south + box.north) / 2;
  const s = Math.sin((Math.max(-85.05112878, Math.min(85.05112878, lat)) * Math.PI) / 180);
  const x = Math.floor(((lon + 180) / 360) * 2 ** z);
  const y = Math.floor(((0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * 2 ** z));
  return { z, x, y: 2 ** z - 1 - y };
}

async function verify(records, overlays) {
  const sample = [];
  const step = Math.max(1, Math.floor(records.length / 30));
  for (let i = 0; i < records.length && sample.length < 30; i += step) sample.push(records[i]);
  const thumbnails = await pool(sample, 3, async (record) => {
    const result = await probe(record.thumbnail, 'image/jpeg');
    return { id: record.id, status: result.status, type: result.type };
  });
  const tileSample = overlays.filter((_, i) => i % Math.max(1, Math.floor(overlays.length / 20)) === 0).slice(0, 20);
  const tiles = await pool(tileSample, 3, async (overlay) => {
    const { z, x, y } = tileAt(overlay.extent, 12);
    const url = overlay.urlTemplate
      .replace('{z}', String(z))
      .replace('{x}', String(x))
      .replace('{-y}', String(y));
    const result = await probe(url, 'image/png');
    return { id: overlay.id, zoom: z, x, y, status: result.status, type: result.type };
  });
  return {
    retrieved: RETRIEVED,
    thumbnailSample: thumbnails.length,
    thumbnailOk: thumbnails.filter((r) => (r.status === 200 || r.status === 206) && /image\//.test(r.type ?? '')).length,
    tileSample: tiles.length,
    tileOk: tiles.filter((r) => (r.status === 200 || r.status === 206) && /image\/png/.test(r.type ?? '')).length,
    examples: thumbnails.slice(0, 4),
    tileExamples: tiles.slice(0, 4),
  };
}

async function main() {
  const search = await cachedSearch();
  const hits = Array.isArray(search?.hits?.hits) ? search.hits.hits : [];
  if (!hits.length) throw new Error('Kartenforum search returned no hits; leaving the catalogue unchanged.');
  const sources = new Map(hits.map((hit) => [hit._source?.map_id, hit._source]));
  const ids = [...sources.keys()].filter(Boolean);
  const metas = await pool(ids, 5, async (mapId) => {
    try {
      return await metadataFor(mapId);
    } catch (error) {
      return { map_id: mapId, __error: String(error.message) };
    }
  });
  const records = [];
  const overlays = [];
  const withheld = {};
  const licenses = {};
  const failed = [];
  for (const meta of metas) {
    if (meta?.__error) {
      failed.push(meta.map_id);
      continue;
    }
    const { record, reason } = kartenforumRecord(meta, sources.get(meta.map_id));
    if (!record) {
      withheld[reason] = (withheld[reason] || 0) + 1;
      continue;
    }
    licenses[record.rights] = (licenses[record.rights] || 0) + 1;
    records.push(record);
    const overlay = overlayOf(record, sources.get(meta.map_id));
    if (overlay) overlays.push(overlay);
  }
  if (!records.length) throw new Error('No eligible Kartenforum records; leaving the catalogue unchanged.');
  records.sort((a, b) => (a.yearStart ?? Infinity) - (b.yearStart ?? Infinity) || a.id.localeCompare(b.id));
  overlays.sort((a, b) => a.id.localeCompare(b.id));
  console.log(`Kartenforum index: ${hits.length} records; admitted ${records.length}, overlays ${overlays.length}`);
  console.log('Licences:', licenses);
  console.log('Withheld:', Object.fromEntries(Object.entries(withheld).sort((a, b) => b[1] - a[1]).slice(0, 8)));
  if (failed.length) console.log(`Metadata fetch failures: ${failed.length}`);
  const verification = await verify(records, overlays);
  console.log('Verification:', verification);

  const recordsPath = resolve(OUT, 'records.json');
  const sourcesPath = resolve(OUT, 'sources.json');
  const overlaysPath = resolve(OUT, 'overlays.json');
  const recordsDoc = JSON.parse(await readFile(recordsPath, 'utf8'));
  const sourcesDoc = JSON.parse(await readFile(sourcesPath, 'utf8'));
  const overlaysDoc = JSON.parse(await readFile(overlaysPath, 'utf8'));
  const generatedAt = new Date().toISOString();
  recordsDoc.shards = [...new Set([...(recordsDoc.shards ?? []), SHARD])].sort();
  recordsDoc.records = recordsDoc.records.filter((record) => record.providerId !== PROVIDER);
  recordsDoc.generatedAt = generatedAt;
  recordsDoc.retrieved = RETRIEVED;
  const selection = {
    considered: hits.length,
    kept: records.length,
    overlays: overlays.length,
    shard: SHARD,
    rightsBasis: licenses,
    withheld,
    failedMetadata: failed.length,
    rule:
      'Every georeferenced map in the SLUB Virtuelles Kartenforum with an affirmative `CC-BY-SA` or `CC-BY-SA 4.0` licence in the official item metadata service, a preserved title and a SLUB thumbnail. The ambiguous `CC-BY-SA & PuD`, rights-reserved `RV-FZ-*`, blank, third-party-attribution and non-commercial values are withheld. Footprints and TMS pyramids are used only where the provider publishes them; no alignment is inferred.',
    verification,
  };
  recordsDoc.selection ??= {};
  recordsDoc.selection['slub-kartenforum'] = selection;
  const provider = {
    id: PROVIDER,
    name: 'Virtuelles Kartenforum der SLUB Dresden',
    operator: 'Sächsische Landesbibliothek – Staats- und Universitätsbibliothek Dresden (SLUB) / Deutsche Fotothek',
    homepage: 'https://kartenforum.slub-dresden.de/',
    home: 'https://kartenforum.slub-dresden.de/',
    institutions: ['Sächsische Landesbibliothek – Staats- und Universitätsbibliothek Dresden (SLUB)', 'Deutsche Fotothek (SLUB Dresden)'],
    rights:
      'The upstream licence string is retained verbatim on every record. Only CC-BY-SA and CC-BY-SA 4.0 are admitted; attribution and share-alike are retained. Ambiguous, rights-reserved, blank and non-commercial values are not imported.',
    attribution: 'SLUB Dresden / Deutsche Fotothek, Virtuelles Kartenforum',
    retrieved: RETRIEVED,
    api: {
      search: SEARCH,
      metadata: `${METADATA}/{map_id}`,
      tile: 'https://tms-1.kartenforum.slub-dresden.de/{map_type}/{file_name}/{z}/{x}/{-y}.png',
      documentation: 'https://kartenforum.slub-dresden.de/',
    },
    apiHosts: ['search.kartenforum.slub-dresden.de', 'api.kartenforum.slub-dresden.de', 'tms-1.kartenforum.slub-dresden.de', 'tms-2.kartenforum.slub-dresden.de', 'fotothek.slub-dresden.de', 'thumbnail.kartenforum.slub-dresden.de'],
    method:
      'Public Kartenforum search index (all 9,068 records), per-item metadata from the official API, per-item licence gate, provider-published footprint polygon and TMS pyramid. Cached and resumable; no arbitrary cap.',
    rightsPolicy: {
      metadata: `${METADATA}/{map_id}`,
      object: 'The Deutsche Fotothek / Kartenforum object page linked from each record.',
      reuse:
        'CC BY-SA (version not stated for CC-BY-SA items; the unversioned Creative Commons URL redirects to the 4.0 deed) and CC BY-SA 4.0. Attribution: SLUB Dresden / Deutsche Fotothek. Share-alike is honoured by retaining the licence and attribution with every displayed image.',
    },
    verification,
  };
  sourcesDoc.providers = [...sourcesDoc.providers.filter((source) => source.id !== PROVIDER), provider].sort((a, b) => a.id.localeCompare(b.id));
  sourcesDoc.generatedAt = generatedAt;

  const keptOverlays = (overlaysDoc.overlays ?? []).filter((overlay) => overlay.providerId !== PROVIDER);
  overlaysDoc.overlays = [...keptOverlays, ...overlays];
  overlaysDoc.generatedAt = generatedAt;
  overlaysDoc.retrieved = RETRIEVED;
  overlaysDoc.source = `${overlaysDoc.source ? overlaysDoc.source + '; ' : ''}SLUB Virtuelles Kartenforum TMS pyramids for CC-BY-SA maps`;
  overlaysDoc.attribution = `${overlaysDoc.attribution ? overlaysDoc.attribution + '; ' : ''}SLUB Dresden / Deutsche Fotothek`;
  overlaysDoc.license = `${overlaysDoc.license ? overlaysDoc.license + ' ' : ''}Kartenforum overlays retain their verbatim CC BY-SA licence and attribution.`;

  const shardDoc = {
    generatedAt,
    retrieved: RETRIEVED,
    providerId: PROVIDER,
    method: selection.rule,
    selection,
    records,
  };
  if (WRITE) {
    await mkdir(dirname(resolve(OUT, 'records', 'kartenforum.json')), { recursive: true });
    await writeFile(recordsPath, JSON.stringify(recordsDoc));
    await writeFile(sourcesPath, JSON.stringify(sourcesDoc, null, 2) + '\n');
    await writeFile(overlaysPath, JSON.stringify(overlaysDoc) + '\n');
    await writeFile(resolve(OUT, 'records', 'kartenforum.json'), JSON.stringify(shardDoc));
  }
  console.log(`Catalogue: ${recordsDoc.records.length} core + ${records.length} Kartenforum records; ${overlaysDoc.overlays.length} overlays; shard ${(Buffer.byteLength(JSON.stringify(shardDoc)) / 1048576).toFixed(2)} MiB`);
  if (WRITE) console.log(`Wrote ${OUT}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}

