/**
 * SLUB Virtuelles Kartenforum rights/import regressions (member 0, 2026-10-20).
 *
 * These pin the behaviours that make the bulk import honest: only affirmative
 * CC-BY-SA values pass, ambiguous/blank/rights-reserved values stay out, the
 * archival title is preserved, and a footprint is only copied from the
 * provider's own polygon (never guessed from a place name).
 */
import test from 'node:test';
import assert from 'node:assert/strict';

import {
  ADMITTED_LICENSES,
  bboxOfGeometry,
  kartenforumRecord,
  licenceFields,
  overlayOf,
  tmsTemplate,
} from '../scripts/harvest-slub-kartenforum.mjs';

const meta = (overrides = {}) => ({
  map_id: 'oai:de:slub-dresden:vk:id-10010368',
  title: '5,13: Sandau (Elbe), um 1855',
  license: 'CC-BY-SA',
  link_thumb_mid: 'https://fotothek.slub-dresden.de/mids/df/dk/0006000/df_dk_0006913_0021.jpg',
  owner: 'SLUB / Deutsche Fotothek',
  permalink: 'https://www.deutschefotothek.de/documents/obj/90030146',
  ppn: 'ppn370974069',
  measures: '29 x 62 cm',
  time_of_publication: '1855-01-01T00:00:00',
  file_name: 'df_dk_0006913_0021',
  ...overrides,
});

const source = (overrides = {}) => ({
  map_id: 'oai:de:slub-dresden:vk:id-10010368',
  keywords: 'Elbe\nStadtplan\n',
  time_published: '1855-01-01',
  tms_urls: ['https://tms-1.kartenforum.slub-dresden.de/tkx/df_dk_0006913_0021'],
  geometry: {
    type: 'Polygon',
    coordinates: [
      [
        [12.02, 52.72],
        [12.16, 52.72],
        [12.16, 52.82],
        [12.02, 52.82],
        [12.02, 52.72],
      ],
    ],
  },
  ...overrides,
});

test('only the two affirmative CC-BY-SA values are admitted', () => {
  assert.deepEqual([...ADMITTED_LICENSES].sort(), ['CC-BY-SA', 'CC-BY-SA 4.0']);
  assert.equal(licenceFields('CC-BY-SA').rightsBasis, 'cc-by-sa');
  assert.equal(licenceFields('CC-BY-SA').licenseVersion, null, 'unknown version stays unknown');
  assert.equal(licenceFields('CC-BY-SA 4.0').licenseVersion, '4.0');
  assert.equal(licenceFields('CC-BY-SA 4.0').licenseUrl, 'https://creativecommons.org/licenses/by-sa/4.0/');
  for (const bad of ['CC-BY-SA & PuD', 'CC-BY-NC', 'RV-FZ-PA', 'RV-FZ-DF', '', null, 'Bundesamt für Kartographie und Geodäsie']) {
    assert.equal(licenceFields(bad), null, `${bad} must be withheld`);
  }
});

test('the record keeps the archival title, owner, date and licence verbatim', () => {
  const { record, reason } = kartenforumRecord(meta(), source());
  assert.equal(reason, undefined);
  assert.equal(record.id, 'slub-kartenforum:10010368');
  assert.equal(record.title, '5,13: Sandau (Elbe), um 1855');
  assert.equal(record.creators.length, 0);
  assert.equal(record.institution, 'SLUB / Deutsche Fotothek');
  assert.equal(record.rights, 'CC-BY-SA');
  assert.equal(record.licenseVersion, null);
  assert.equal(record.rightsUrl, 'https://creativecommons.org/licenses/by-sa/');
  assert.equal(record.yearStart, 1855);
  assert.equal(record.dateDisplay, '1855');
  assert.equal(record.physicalSize, '29 x 62 cm');
  assert.deepEqual(record.extent, { west: 12.02, east: 12.16, south: 52.72, north: 52.82 });
  assert.deepEqual(record.subjects, ['Elbe', 'Stadtplan']);
  assert.match(record.metadataSource, /^https:\/\/api\.kartenforum\.slub-dresden\.de\/maps\/oai:/);
  assert.match(record.viewerUrl, /^https:\/\/kartenforum\.slub-dresden\.de\/\?map_id=/);
});

test('records without a provider footprint stay usable but get no invented extent', () => {
  const { record } = kartenforumRecord(meta({ map_id: 'oai:de:slub-dresden:vk:id-10010542' }), source({ geometry: null, tms_urls: [] }));
  assert.equal(record.extent, undefined);
  assert.match(record.geoNote, /does not state a footprint/);
});

test('test records, missing thumbnails and non-CC licences are withheld', () => {
  assert.match(kartenforumRecord(meta({ title: 'Düsseldorf (Test)' }), source()).reason, /test record/);
  assert.match(kartenforumRecord(meta({ link_thumb_mid: '', link_thumb_small: '' }), source()).reason, /thumbnail/);
  assert.match(kartenforumRecord(meta({ license: 'RV-FZ-DF' }), source()).reason, /rights withheld/);
  assert.match(kartenforumRecord(meta({ license: 'CC-BY-SA & PuD' }), source()).reason, /rights withheld/);
  assert.match(kartenforumRecord(meta({ license: '' }), source()).reason, /rights withheld/);
});

test('footprint extraction accepts Polygon and MultiPolygon but not malformed boxes', () => {
  assert.deepEqual(bboxOfGeometry(source().geometry), { west: 12.02, east: 12.16, south: 52.72, north: 52.82 });
  assert.deepEqual(
    bboxOfGeometry({
      type: 'MultiPolygon',
      coordinates: [[[[1, 2], [3, 2], [3, 4], [1, 4], [1, 2]]], [[[10, 20], [12, 20], [12, 22], [10, 22], [10, 20]]]],
    }),
    { west: 1, east: 12, south: 2, north: 22 },
  );
  assert.equal(bboxOfGeometry({ type: 'Polygon', coordinates: [[[1, 2], [0, 2], [0, 4], [1, 2]]] }), null);
  assert.equal(bboxOfGeometry({ type: 'Point', coordinates: [1, 2] }), null);
});

test('only a provider-published TMS pyramid becomes an overlay', () => {
  assert.equal(tmsTemplate(['https://tms-1.kartenforum.slub-dresden.de/cm/df_dk_0006913_0021']), 'https://tms-1.kartenforum.slub-dresden.de/cm/df_dk_0006913_0021/{z}/{x}/{-y}.png');
  assert.equal(tmsTemplate(['https://example.test/tiles/x']), null);
  const { record } = kartenforumRecord(meta(), source());
  const overlay = overlayOf(record, source());
  assert.equal(overlay.kind, 'xyz');
  assert.equal(overlay.recordId, record.id);
  assert.match(overlay.urlTemplate, /\{z\}\/\{x\}\/\{-y\}\.png$/);
  assert.deepEqual(overlay.extent, record.extent);
  assert.equal(overlay.license, 'CC-BY-SA');
  const noTiles = kartenforumRecord(meta(), source({ tms_urls: [] })).record;
  assert.equal(overlayOf(noTiles, source({ tms_urls: [] })), null);
});
